
/* ================= TASKS (new app) ================= */
const it=(t,o={})=>({t,d:0,kids:[],...o});
const TL={mine:{n:'My tasks',f:'Personal',ic:'user',c:'#0EA5A4',items:[it('Plan next week',{due:'Fri',kids:[it('Review Planner objectives',{d:1}),it('Block 2 deep-work mornings')]}),it('Reply to Victor about the retainer',{due:'Today',pri:'high'}),it('Renew domain for EfficusAI',{due:'Mon'}),it('Read “$100M Leads” ch. 4',{private:1})]},
challenge:{n:'Funnel Challenge',f:'Personal',ic:'flag',c:'#F07C1A',items:[it('Day 1: Why funnels beat websites',{d:1}),it('Day 2: The value ladder',{d:1}),it('Day 3: Draft email',{due:'Fri',who:'TR',kids:[it('Hook from John’s external desires'),it('Story: the funnel guy who vanished'),it('Call to action: join the quiz')]}),it('Day 4: Traffic basics',{due:'Next week'}),it('Book cover brief to Ayesha',{who:'AR',due:'Tue'})]},
team:{n:'Build team',f:'Team',ic:'team',c:'#2B5CF0',items:[it('Check GHL calendar sync',{who:'TR',due:'Today',pri:'high'}),it('Set up quiz scoring in GHL',{who:'BK',due:'Wed',kids:[it('Map 3 result pages'),it('Test with 5 fake leads')]}),it('Update QA checklist',{who:'BK',d:1})]},
content:{n:'Content ideas',f:'Team',ic:'social',c:'#E9488F',items:[it('Reel: 3 funnel myths',{who:'SN'}),it('Case study: 41 booked calls',{who:'SN',due:'Thu'}),it('Carousel: value ladder in 5 slides',{who:'AR'})]}};
const TV={view:'list'};
const TNAV=[['tasks/today','Today','sun',4],['tasks/upcoming','Upcoming','cal'],['tasks/inbox','Inbox','inbox',2],['tasks/assigned','Assigned by me','send'],['tasks/teammates','Teammates','users']];
function tShell(cur,body,crumbs,o={}){const fol=(f)=>Object.entries(TL).filter(([k,l])=>l.f===f).map(([k,l])=>`<a href="#/tasks/list/${k}" ${RT.p[1]===k?'aria-current="page"':''} data-ctx="tlist:${k}"><span class="tl-ic" style="--c:${l.c}">${ic(l.ic,14)}</span><span>${l.n}</span><span class="count">${cnt(l.items)}</span></a>`).join('');
return shell('tasks',{nav:TNAV,cur,body,crumbs:crumbs||[['Tasks']],sideMid:`<details class="coll" open><summary class="side-sec sx">${ic('down',14)}${ic('lock',12)} Personal · only you</summary><div class="side-list">${fol('Personal')}</div></details><details class="coll" open><summary class="side-sec sx">${ic('down',14)}${ic('team',12)} Team · ${oname()}</summary><div class="side-list">${fol('Team')}</div></details><button class="addrow" data-act="newlist">${ic('plus',16)}New list or folder</button>`,barRight:`<button class="btn primary sm" data-act="tcap">${ic('plus',16,'',2.2)}<span class="hide-m">Add task</span></button>`,...o})}
const cnt=L=>L.reduce((n,i)=>n+(i.d?0:1)+cnt(i.kids),0);
function outline(L,path,depth=0){return L.map((x,i)=>{const p=path+'.'+i;return `<li class="ol-i ${x.d?'done':''}" data-ctx="titem:${p}"><div class="ol-row" style="--d:${depth}"><span class="grip" aria-hidden="true">⋮⋮</span>${x.kids.length?`<button class="ol-tw" data-act="ttw" aria-label="Collapse">${ic('down',14)}</button>`:'<span class="ol-tw"></span>'}<button class="ol-cb" role="checkbox" aria-checked="${!!x.d}" data-act="tchk:${p}" aria-label="Complete"><i>${ic('check',13,'',3)}</i></button><span class="ol-t" contenteditable="true" spellcheck="false">${x.t}</span>${x.private?`<span class="pill" style="height:20px">${ic('lock',11)}Private</span>`:''}${x.who&&x.who!=='TR'?av(x.who,22):''}${x.pri==='high'?`<span class="pri" style="--c:#F07C1A">${ic('flag',13)}</span>`:''}${x.due?`<span class="due-c ${x.due==='Today'?'soon':''}">${x.due}</span>`:''}<button class="iconbtn ol-more" aria-label="Task menu" data-act="tmenu:${p}">${ic('more',16)}</button></div>${x.kids.length?`<ul>${outline(x.kids,p,depth+1)}</ul>`:''}</li>`}).join('')}
function mindmap(l){const N=l.items.length,R=230;return `<div class="mm-wrap"><svg viewBox="-460 -300 920 600" class="mm-svg" role="img" aria-label="Mind map of ${l.n}">${l.items.map((x,i)=>{const a=(i/N)*Math.PI*2-Math.PI/2,X=Math.cos(a)*R,Y=Math.sin(a)*R*.72;return `<path d="M0 0 C ${X*.5} 0, ${X*.5} ${Y}, ${X} ${Y}" class="mm-ln" style="stroke:${l.c}"/>${x.kids.map((k,j)=>{const b=a+(j-(x.kids.length-1)/2)*.32,X2=Math.cos(b)*(R+150),Y2=Math.sin(b)*(R+150)*.72;return `<path d="M${X} ${Y} L${X2} ${Y2}" class="mm-ln thin" style="stroke:${l.c}"/><g transform="translate(${X2} ${Y2})"><rect x="-70" y="-15" width="140" height="30" rx="15" class="mm-n2"/><text text-anchor="middle" dy="4" class="mm-t2">${esc(k.t.slice(0,22))}</text></g>`}).join('')}<g transform="translate(${X} ${Y})"><rect x="-92" y="-20" width="184" height="40" rx="12" class="mm-n1 ${x.d?'d':''}" style="stroke:${l.c}"/><text text-anchor="middle" dy="5" class="mm-t1">${esc(x.t.slice(0,24))}</text></g>`}).join('')}<g><rect x="-90" y="-28" width="180" height="56" rx="18" style="fill:${l.c}"/><text text-anchor="middle" dy="6" class="mm-t0">${esc(l.n)}</text></g></svg></div>`}
function flat(L,out=[]){L.forEach(x=>{out.push(x);flat(x.kids,out)});return out}
VIEWS.tasks=p=>{const pg=p[0]||'today';
if(pg==='list'){const k=p[1]||'mine',l=TL[k];const V=[['list','List','list'],['board','Board','board'],['table','Table','table'],['mind','Mind map','mindmap'],['cal','Calendar','cal']];let v='';
if(TV.view==='list')v=`<ul class="outline">${outline(l.items,k)}</ul><button class="addrow" data-act="tadd:${k}">${ic('plus',16)}Add a task <kbd>Enter</kbd> · indent with <kbd>Tab</kbd></button>`;
if(TV.view==='board')v=`<div class="kanban">${[['To do',x=>!x.d&&x.due!=='Today'],['Today',x=>!x.d&&x.due==='Today'],['Done',x=>x.d]].map(([n,f])=>`<div class="kcol"><div class="kcol-h"><b>${n}</b></div>${l.items.filter(f).map(x=>`<div class="kcard"><b>${x.t}</b><span class="foot">${x.who?av(x.who,22):''}${x.due||''}${x.kids.length?`<span style="margin-left:auto">${x.kids.length} sub</span>`:''}</span></div>`).join('')}</div>`).join('')}</div>`;
if(TV.view==='table')v=`<div class="tblwrap"><table class="tbl"><thead><tr><th>Task</th><th>Who</th><th>Due</th><th>Priority</th><th>Done</th></tr></thead><tbody>${flat(l.items).map(x=>`<tr><td class="t1">${x.t}</td><td data-l="Who">${x.who?av(x.who):'—'}</td><td data-l="Due">${x.due||'—'}</td><td data-l="Priority">${x.pri||'—'}</td><td data-l="Done">${x.d?ic('check',16,'',2.6):''}</td></tr>`).join('')}</tbody></table></div>`;
if(TV.view==='mind')v=mindmap(l);
if(TV.view==='cal')v=`<div class="cal">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dh">${d}</div>`).join('')}${Array.from({length:14},(_,i)=>`<div class="dc ${i===3?'today':''}"><span class="dn">${9+i}</span>${flat(l.items).filter(x=>({Today:3,Fri:4,Mon:7,Tue:8,Wed:9,Thu:3}[x.due])===i).map(x=>`<span class="ev" style="--c:${l.c}">${x.t}</span>`).join('')}</div>`).join('')}</div>`;
return tShell('',`<div class="tl-head"><span class="tl-ic big" style="--c:${l.c}">${ic(l.ic,22)}</span><div><h1 class="h1">${l.n}</h1><p class="hint">${l.f==='Personal'?ic('lock',12)+' Only you can see this list. Items marked Private never show to managers, even as names.':ic('team',12)+' Everyone in '+oname()+' with Tasks access can see and add to this list.'}</p></div><span class="grow"></span>${l.f==='Team'?avs(['TR','BK','SN']):''}<button class="iconbtn" data-act="tmenul:${k}" aria-label="List menu">${ic('more')}</button></div><div class="toolbar">${vsw(V.map(([a,b,c])=>[a,b,c]),TV.view,'tview')}<span class="grow"></span><button class="chip" data-act="chipt" aria-pressed="false">Hide completed</button></div>${v}`,[['Tasks'],[l.f],[l.n]])}
if(pg==='today'){const all=Object.entries(TL).flatMap(([k,l])=>flat(l.items).map(x=>({...x,l,k})));const today=all.filter(x=>x.due==='Today'&&!x.d);
return tShell('tasks/today',`<div class="tl-head"><span class="tl-ic big" style="--c:#FFB547">${ic('sun',22)}</span><div><h1 class="h1">Today</h1><p class="hint">Thursday 12 November · from your lists, plus what’s assigned to you in Projects and Planner.</p></div></div>
<div class="capture"><span>${ic('plus',18)}</span><input id="tcapi" placeholder="Add a task… e.g. “Call Harry tomorrow 3pm @Sana #challenge !high”" aria-label="Add a task"><kbd>Enter</kbd></div>
<section class="panel"><div class="sec-h"><h2>From your lists</h2><span class="n">${today.length}</span></div><ul class="outline flatol">${today.map(x=>`<li class="ol-i" data-ctx="titem:x"><div class="ol-row"><button class="ol-cb" role="checkbox" aria-checked="false" data-act="chipt" aria-label="Complete"><i>${ic('check',13,'',3)}</i></button><span class="ol-t">${x.t}</span><span class="tl-ic" style="--c:${x.l.c}">${ic(x.l.ic,12)}</span><small class="muted">${x.l.n}</small></div></li>`).join('')}</ul></section>
<section class="panel" style="margin-top:16px"><div class="sec-h"><h2>From other apps</h2><span class="hint" style="margin-left:auto">Open them where they live</span></div><div class="rows">${MYDAY.filter(x=>x[0]!=='tasks').slice(0,4).map(([a,t,c,d,pr,h])=>`<a class="linkrow" href="#/${h}">${plate(app(a),26)}<span class="main"><b>${t}</b><small>${c}</small></span><span class="due-c ${d==='Today'?'soon':d==='Overdue'?'od':''}">${d}</span></a>`).join('')}</div></section>`,[['Tasks'],['Today']])}
if(pg==='upcoming'){const days=['Today','Fri','Mon','Tue','Wed','Next week'];const all=Object.values(TL).flatMap(l=>flat(l.items).map(x=>({...x,l})));return tShell('tasks/upcoming',`${head('Upcoming','The next two weeks across your lists.')}<div class="upc">${days.map(d=>`<section class="panel"><div class="sec-h"><h2>${d}</h2></div><div class="rows">${all.filter(x=>x.due===d&&!x.d).map(x=>`<div class="row" style="min-height:44px"><span class="tl-ic" style="--c:${x.l.c}">${ic(x.l.ic,12)}</span><div class="main"><b>${x.t}</b><small>${x.l.n}</small></div></div>`).join('')||'<p class="hint" style="padding:0 12px 12px">Nothing yet.</p>'}</div></section>`).join('')}</div>`,[['Tasks'],['Upcoming']])}
if(pg==='inbox')return tShell('tasks/inbox',`${head('Inbox','Quick captures and tasks sent from other apps. Sort them into a list when you have a minute.')}<ul class="outline flatol">${['Idea: quiz for Aurj parents','From Customer Avatar: Interview 5 real Johns'].map(t=>`<li class="ol-i"><div class="ol-row"><button class="ol-cb" role="checkbox" aria-checked="false" data-act="chipt" aria-label="Complete"><i>${ic('check',13,'',3)}</i></button><span class="ol-t">${t}</span><button class="btn quiet sm" data-act="toast:Moved to “My tasks”.:ok">Move to list</button></div></li>`).join('')}</ul>`,[['Tasks'],['Inbox']]);
if(pg==='assigned')return tShell('tasks/assigned',`${head('Assigned by me','Tasks you gave to teammates, and where they stand.')}<div class="tblwrap"><table class="tbl"><thead><tr><th>Task</th><th>To</th><th>List</th><th>Due</th><th>Status</th></tr></thead><tbody>${[['Book cover brief','AR','Funnel Challenge','Tue','Not started'],['Set up quiz scoring in GHL','BK','Build team','Wed','In progress'],['Case study: 41 booked calls','SN','Content ideas','Thu','In progress']].map(([t,k,l,d,s])=>`<tr><td class="t1">${t}</td><td data-l="To">${av(k)}</td><td data-l="List">${l}</td><td data-l="Due">${d}</td><td data-l="Status"><span class="pill ${s==='In progress'?'blue':''}">${s}</span></td></tr>`).join('')}</tbody></table></div>`,[['Tasks'],['Assigned by me']]);
if(pg==='teammates'){const k=p[1];if(k){return tShell('tasks/teammates',`${back('tasks/teammates','All teammates')}<div class="tl-head" style="margin-top:10px">${av(k,52)}<div><h1 class="h1">${PEOPLE[k][0]}’s tasks</h1><p class="hint">Lists ${PEOPLE[k][0].split(' ')[0]} created for themself, plus tasks others gave them. Private items show as a count only.</p></div><span class="grow"></span><button class="btn primary" data-act="tcap">${ic('plus',18,'',2.2)}Give a task</button></div><div class="grid2">${[['Copy drafts',['Quiz questions v2','Results page copy','Email 3 subject lines']],['Learning',['Finish copywriting course module 5']]].map(([n,L])=>`<section class="panel"><div class="sec-h"><h2>${n}</h2><span class="n">${L.length}</span></div><ul class="outline flatol">${L.map(t=>`<li class="ol-i"><div class="ol-row"><span class="ol-cb"><i></i></span><span class="ol-t">${t}</span></div></li>`).join('')}</ul></section>`).join('')}</div><p class="hint" style="margin-top:10px">${ic('lock',12)} 3 private tasks not shown.</p>`,[['Tasks'],['Teammates','tasks/teammates'],[PEOPLE[k][0]]])}
return tShell('tasks/teammates',`${head('Teammates','See what each person is working on and has planned for themself. Only managers with “See teammates’ tasks” can open this.')}<div class="cardgrid">${Object.keys(PEOPLE).filter(x=>x!=='TR').map((k,i)=>`<a class="card" href="#/tasks/teammates/${k}"><span style="display:flex;gap:12px;align-items:center">${av(k,44)}<span><h3>${PEOPLE[k][0]}</h3><small class="muted">${PEOPLE[k][2]}</small></span></span><div class="kpis sm">${[[4+i,'Open'],[i%3,'Due today'],[i===1?1:0,'Overdue']].map(([b,s])=>`<div><b>${b}</b><span>${s}</span></div>`).join('')}</div><div class="foot">Own lists: ${['Copy drafts, Learning','Design queue','GHL builds','Strategy notes','Ad tests'][i]}</div></a>`).join('')}</div>`,[['Tasks'],['Teammates']])}
return tShell('tasks/today','')};
CTX.titem=v=>[['check','Complete','toast:Completed.:ok','','Ctrl Enter'],['plus','Add sub-task','toast:Sub-task added.'],['user','Assign to…','tcap'],['cal','Due date…','noop'],['flag','Priority…','noop'],['lock','Make private','toast:Only you can see it now.:ok'],'-',['folder','Move to list…','noop'],['projects','Send to a project','toast:Sent to Projects. It now lives there and links back here.:ok'],['copy','Duplicate','toast:Duplicated.:ok'],['link','Copy link','toast:Link copied.:ok'],'-',['trash','Delete','toast:Deleted. Undo for 10 seconds.','danger','Del']];
CTX.tlist=v=>[['edit','Rename','noop'],['brand','Icon and colour','noop'],['copy','Duplicate list','toast:Duplicated.:ok'],['users','Share with…','noop'],['projects','Turn into a project','toast:Creates a project with these tasks. Future: needs your approval.'],'-',['archive','Archive list','toast:Archived.','danger']];
Object.assign(ACT,{tview:v=>{TV.view=v;draw()},tchk:(v,t)=>{const r=t.closest('.ol-i');r.classList.toggle('done');t.setAttribute('aria-checked',r.classList.contains('done'))},ttw:(v,t)=>t.closest('.ol-i').classList.toggle('closed'),
tmenu:(v,t)=>{const r=t.getBoundingClientRect();ctxMenu({preventDefault(){},clientX:r.left,clientY:r.bottom},CTX.titem(v))},tmenul:(v,t)=>{const r=t.getBoundingClientRect();ctxMenu({preventDefault(){},clientX:r.left-180,clientY:r.bottom},CTX.tlist(v))},
tadd:k=>{TL[k].items.push(it('New task'));draw();setTimeout(()=>{const e=$$('.ol-t').at(-1);e?.focus();document.execCommand?.('selectAll')},30)},
tcap:()=>dlg({title:'Add a task',body:`<div class="field" style="margin-top:12px"><label for="tq">Task</label><input id="tq" placeholder="e.g. Send cover brief to Ayesha Tue #challenge"></div><div class="row2"><div class="field"><label for="tqa">For</label><select id="tqa">${Object.keys(PEOPLE).map(k=>`<option>${PEOPLE[k][0]}</option>`).join('')}</select></div><div class="field"><label for="tql">List</label><select id="tql">${Object.values(TL).map(l=>`<option>${l.n}</option>`).join('')}</select></div></div>`,acts:[['Cancel','noop'],['Add','toast:Task added. They’ll get a notification.:ok','primary']]}),
newlist:()=>dlg({title:'New list or folder',body:`<div class="vsw" style="margin:12px 0">${[['l','List'],['f','Folder']].map(([k,l],i)=>`<button aria-pressed="${!i}" data-act="noop">${l}</button>`).join('')}</div><div class="field"><label for="nl">Name</label><input id="nl"></div><div class="field"><label for="ns">Where</label><select id="ns"><option>Personal · only you</option><option>Team · ${oname()}</option></select></div>`,acts:[['Cancel','noop'],['Create','toast:Created.:ok','primary']]})});
document.addEventListener('keydown',e=>{if(e.target.id==='tcapi'&&e.key==='Enter'&&e.target.value.trim()){TL.mine.items.unshift(it(e.target.value.trim(),{due:'Today'}));e.target.value='';draw();toast('Added to My tasks for today.','ok',1500)}
 if(e.target.classList?.contains('ol-t')&&e.key==='Tab'){e.preventDefault();toast(e.shiftKey?'Outdented.':'Indented under the task above.','ok',900)}});
SEARCH.push(()=>Object.entries(TL).flatMap(([k,l])=>flat(l.items).filter(x=>!x.private).map(x=>({app:'tasks',t:x.t,s:l.n+(x.due?' · '+x.due:''),href:'tasks/list/'+k,me:!x.who||x.who==='TR',od:false}))));
